#ifndef SCAMP_IMAGE_HPP
#define SCAMP_IMAGE_HPP

#include "scamptrie_base.h"

#include <array>
#include <bitset>
#include <cstdint>
#include <string>
#include <vector>

// Locator of a node record: stage 0..10 and the first charged cell.
struct ImageLoc {
    int stage = -1;      // -1 means "no node" (null root)
    uint32_t cell = 0;
};

struct ImageFront {
    uint64_t key = 0;
    ImageLoc loc;
};

// Complete, self-contained packed memory image.
struct ImageData {
    ImageLoc root;                                        // depth-0 root
    std::vector<ImageFront> front16, front64;              // sorted by key
    std::array<uint32_t, RAM_NUM> cells{};                 // charged cells per stage
    std::array<std::vector<std::bitset<256>>, RAM_NUM> banks; // ceil(cells/2) rows
    std::vector<uint64_t> bitmaps;                         // NI bitmap dictionary
    std::vector<uint32_t> nexthops;                        // NI vector
};

class MemoryImage {
public:
    MemoryImage() = default;

    // Validate the complete image and, only when it is fully consistent,
    // replace the loaded state.  Never touches the live FIB or saved images.
    bool load(const ImageData& proposed);

    // Longest prefix match against the loaded serialized image only.
    nexthop_t lookup(ip6_t ip) const;

    bool valid() const { return valid_; }

private:
    ImageData data_;
    bool valid_ = false;
};

std::string image_word_hex(const std::bitset<256>& bits);
std::bitset<256> image_word_from_hex(const std::string& text);

#endif // SCAMP_IMAGE_HPP
