#ifndef SCAMP_IMAGE_IO_HPP
#define SCAMP_IMAGE_IO_HPP

#include "image.hpp"

#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>

// The internal wire format is produced by the fixed front end; this file only
// reads and writes field values, never image semantics.

inline uint64_t hex64(const std::string& s) {
    if (s.empty()) throw std::runtime_error("hex field");
    uint64_t v = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        uint64_t d;
        if (c >= '0' && c <= '9') d = static_cast<uint64_t>(c - '0');
        else if (c >= 'a' && c <= 'f') d = static_cast<uint64_t>(c - 'a' + 10);
        else throw std::runtime_error("hex digit");
        v = (v << 4) | d;
    }
    return v;
}

inline ip6_t read_ip() {
    std::string a, b;
    if (!(std::cin >> a >> b)) throw std::runtime_error("wire address");
    ip6_t ip;
    ip.hi = hex64(a);
    ip.lo = hex64(b);
    return ip;
}

inline void image_write_json(const ImageData& d) {
    std::string out;
    out.reserve(4096 + 66 * (d.banks[0].size() + 64));
    char buf[64];
    auto loc = [&out](const ImageLoc& x) {
        out += '[';
        out += std::to_string(x.stage);
        out += ',';
        out += std::to_string(x.cell);
        out += ']';
    };
    auto fronts = [&out, &buf](const std::vector<ImageFront>& v, int width) {
        out += '[';
        for (size_t i = 0; i < v.size(); ++i) {
            if (i) out += ',';
            snprintf(buf, sizeof(buf), "%s%0*llx", "\"", width,
                     static_cast<unsigned long long>(v[i].key));
            out += buf;
            snprintf(buf, sizeof(buf), ",%d,%u]", v[i].loc.stage, v[i].loc.cell);
            out += buf;
        }
        out += ']';
    };

    out += "{\"root\":";
    if (d.root.stage < 0) out += "null";
    else loc(d.root);
    out += ",\"front16\":";
    fronts(d.front16, 4);
    out += ",\"front64\":";
    fronts(d.front64, 16);
    out += ",\"cells\":[";
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) out += ',';
        out += std::to_string(d.cells[s]);
    }
    out += "],\"banks\":[";
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) out += ',';
        out += '[';
        for (size_t i = 0; i < d.banks[s].size(); ++i) {
            if (i) out += ',';
            out += '"';
            out += image_word_hex(d.banks[s][i]);
            out += '"';
        }
        out += ']';
    }
    out += "],\"bitmaps\":[";
    for (size_t i = 0; i < d.bitmaps.size(); ++i) {
        if (i) out += ',';
        snprintf(buf, sizeof(buf), "\"%016llx\"",
                 static_cast<unsigned long long>(d.bitmaps[i]));
        out += buf;
    }
    out += "],\"nexthops\":[";
    for (size_t i = 0; i < d.nexthops.size(); ++i) {
        if (i) out += ',';
        out += std::to_string(d.nexthops[i]);
    }
    out += "]}";
    std::cout << out;
}

inline ImageData image_read_wire() {
    ImageData d;
    if (!(std::cin >> d.root.stage >> d.root.cell)) throw std::runtime_error("wire root");
    for (int f = 0; f < 2; ++f) {
        std::vector<ImageFront>* v = (f == 0) ? &d.front16 : &d.front64;
        size_t n;
        if (!(std::cin >> n)) throw std::runtime_error("wire front count");
        if (n > 4096) throw std::runtime_error("wire front bound");
        v->resize(n);
        for (size_t i = 0; i < n; ++i) {
            std::string key;
            if (!(std::cin >> key >> (*v)[i].loc.stage >> (*v)[i].loc.cell))
                throw std::runtime_error("wire front entry");
            (*v)[i].key = hex64(key);
        }
    }
    for (int s = 0; s < RAM_NUM; ++s)
        if (!(std::cin >> d.cells[s])) throw std::runtime_error("wire cells");
    for (int s = 0; s < RAM_NUM; ++s) {
        size_t n;
        if (!(std::cin >> n)) throw std::runtime_error("wire bank count");
        if (n > 65536) throw std::runtime_error("wire bank bound");
        d.banks[s].resize(n);
        for (size_t i = 0; i < n; ++i) {
            std::string text;
            if (!(std::cin >> text)) throw std::runtime_error("wire word");
            d.banks[s][i] = image_word_from_hex(text);
        }
    }
    size_t n;
    if (!(std::cin >> n)) throw std::runtime_error("wire bitmaps");
    if (n > 8193) throw std::runtime_error("wire bitmaps bound");
    d.bitmaps.resize(n);
    for (size_t i = 0; i < n; ++i) {
        std::string text;
        if (!(std::cin >> text)) throw std::runtime_error("wire bitmap");
        d.bitmaps[i] = hex64(text);
    }
    if (!(std::cin >> n)) throw std::runtime_error("wire nexthops");
    if (n > 8192) throw std::runtime_error("wire nexthops bound");
    d.nexthops.resize(n);
    for (size_t i = 0; i < n; ++i)
        if (!(std::cin >> d.nexthops[i])) throw std::runtime_error("wire nexthop");
    if (!std::cin) throw std::runtime_error("wire input");
    return d;
}

#endif // SCAMP_IMAGE_IO_HPP
